nodes=['198948', '194947', '218370', '202949', '282455', '248143']
import cmath, math; v=[float(x)/224782.0 for x in nodes]; eigs=[sum(v[n]*cmath.exp(-2j*math.pi*k*n/6) for n in range(6)) for k in range(6)]; poly=[1.0]; exec("for e in eigs:\n poly=[poly[0]]+[poly[i]-e*poly[i-1] for i in range(1,len(poly))]+[-e*poly[-1]]"); c=[x.real for x in poly]; M=[[v[(j-i)%6] for j in range(6)] for i in range(6)]; P=[[1.0 if i==j else 0.0 for j in range(6)] for i in range(6)]; Tot=[[c[6] if i==j else 0.0 for j in range(6)] for i in range(6)]; exec("for p in range(5,-1,-1):\n P=[[sum(P[i][k]*M[k][j] for k in range(6)) for j in range(6)] for i in range(6)]\n Tot=[[Tot[i][j]+c[p]*P[i][j] for j in range(6)] for i in range(6)]"); err=math.sqrt(sum(Tot[i][j]**2 for i in range(6) for j in range(6))); print(f"2.CAYLEY_HAMILTON_ANNIHILATION: 6th_Degree_Matrix_Zero_Residual={err:.4e} (36_Cells_Zeroed={err<1e-10})")
